"""Broader local referrals with explicit recommendation and evidence boundaries."""
import html
import json
import shutil
from editorial import write_editorial_page

PEOPLE = [
 dict(slug='c-and-j-automotive-upper-chichester',name='C&J Automotive & Tire — Upper Chichester',category='automotive',label='Auto repair & tire care',initials='C&J',phone='610-485-3103',tel='+16104853103',website='https://candjautorepair.com/upper-chi/',detail='2909 Chichester Ave., Upper Chichester Township, PA 19061',intro='A local automotive connection for the next service conversation.',copy='The Upper Chichester location publishes its address and direct phone on C&J’s official website. The company describes maintenance, diagnostics, tires, brakes and other repair services across its locations. Ask this shop to confirm the service for your vehicle, current pricing and appointment availability.',questions=['Which vehicle, year and concern should I describe before booking?','What does the diagnostic charge include?','Can I review the estimate and approve changes before work proceeds?'],sources=[('Official Upper Chichester location','https://candjautorepair.com/upper-chi/'),('Company service information','https://candjautorepair.com/services/')]),
 dict(slug='caitlin-kerezsi',name='Caitlin Kerezsi',category='realestate',label='Real estate · The Kerezsi Real Estate Team',initials='CK',phone='610-368-9912',tel='+16103689912',website='https://ckerezsi.kw.com/about',detail='Keller Williams Real Estate · Media-area professional profile',intro='A conversation about your next home chapter.',copy='Caitlin’s Keller Williams profile describes work with buyers and sellers, including first-time buyers. Her public professional profile identifies The Kerezsi Real Estate Team. Discuss your goals, location, timing and the services she would provide directly.',questions=['What would working together look like for my buying or selling plans?','Who will be my main point of contact and how will we communicate?','Which services, responsibilities and fees would be agreed in writing?'],sources=[('Official Keller Williams profile','https://ckerezsi.kw.com/about')]),
 dict(slug='megan-kerezsi',name='Megan Kerezsi',category='realestate',label='Real estate · The Kerezsi Real Estate Team',initials='MK',phone='610-368-4189',tel='+16103684189',website='https://mksellshomes.kw.com/about',detail='Keller Williams Real Estate · The Kerezsi Real Estate Team',intro='Start with the move you want to make.',copy='Megan’s Keller Williams profile describes her work with home buyers and sellers and identifies The Kerezsi Real Estate Team. Ask about your particular area, preferred timing and the process for an initial conversation. Confirm current representation and service terms directly.',questions=['How would you approach my particular buying or selling plans?','What information would help our first conversation?','How are the proposed services, fees and communication expectations documented?'],sources=[('Official Keller Williams profile','https://mksellshomes.kw.com/about')]),
 dict(slug='libbi-skivo',name='Libbi Skivo',category='realestate',label='Real estate · The Kristin & Libbi Team',initials='LS',phone='215-316-2843',tel='+12153162843',website='https://www.kristinandlibbi.com/agent/libbi-skivo-team-leader/',detail='Team Leader · The Kristin & Libbi Team',intro='Make the next conversation about your goals.',copy='Libbi’s official team profile identifies her as a team leader and describes buyer and seller representation in the Philadelphia area. Discuss the property location, your goals and how the team would work with you. Confirm coverage, current availability and written service terms directly.',questions=['What role would you and your team each have in my transaction?','How will we discuss preparation, timing and communication?','What services and fees should I review before deciding to work together?'],sources=[('Official team profile','https://www.kristinandlibbi.com/agent/libbi-skivo-team-leader/')])
]


def add(out,origin,pages):
    e=html.escape
    def link(url,label,cls=''):
        return f'<a class="{cls}" href="{e(url,quote=True)}">{e(label)}</a>'
    def render(path,title,desc,body):
        write_editorial_page(out,origin,pages,path,title,desc,'<div class="wrap local-help-page">'+body+'</div>')
        target=out/path.strip('/')/'index.html'
        target.write_text(target.read_text().replace('</head>','<link rel="stylesheet" href="/assets/local-help.css"></head>'))
    def card(p):
        return '<article class="local-pro-card"><div class="local-monogram" aria-hidden="true">'+e(p['initials'])+'</div><span class="local-status">OWNER-RECOMMENDED</span><h3>'+link('/businesses/'+p['slug']+'/',p['name'])+'</h3><p>'+e(p['label'])+'</p><p>'+e(p['detail'])+'</p>'+link('/businesses/'+p['slug']+'/','Meet '+p['name']+' →')+'</article>'
    evidence='<p class="local-evidence">Recommended by Wazoozie’s owner. Public business details checked November 6, 2026 using the linked business sources. This records the recommendation and source check; it does not claim an independent license, insurance, certification or workmanship inspection. No rating, paid partnership or guaranteed outcome is implied.</p>'
    for p in PEOPLE:
        parent='/auto-mechanics/' if p['category']=='automotive' else '/real-estate-agents/'
        body='<div class="breadcrumb">'+link('/local-help/','Local help')+'<span>/</span>'+link(parent,'Auto mechanics' if p['category']=='automotive' else 'Real estate agents')+'</div><section class="local-profile-hero"><div><span class="local-status">OWNER-RECOMMENDED · PUBLIC SOURCES LINKED</span><h1>'+e(p['name'])+'</h1><p class="local-lede">'+e(p['intro'])+'</p><p>'+e(p['label'])+'</p><p>'+e(p['detail'])+'</p><div class="local-actions">'+link('tel:'+p['tel'],'Call '+p['phone'],'btn primary')+link(p['website'],'Visit the official website ↗','btn outline')+'</div></div><div class="local-profile-mark" aria-hidden="true">'+e(p['initials'])+'</div></section><section class="local-profile-body"><div><h2>A useful first introduction.</h2><p>'+e(p['copy'])+'</p><h2>Three things to ask.</h2><ol>'+''.join('<li>'+e(q)+'</li>' for q in p['questions'])+'</ol><p>Contact goes directly to the listed business or professional. Wazoozie does not send this inquiry to Middletown HVAC or book an appointment here.</p></div><aside><h2>What this listing tells you.</h2>'+evidence+'<h3>Public sources</h3><ul>'+''.join('<li>'+link(url,label+' ↗')+'</li>' for label,url in p['sources'])+'</ul>'+('<p>'+link('https://www.pals.pa.gov/pages/search.html','Check Pennsylvania license records ↗')+'</p><p>A business profile is not a current license-status verification. Confirm the appropriate state and professional record directly.</p>' if p['category']=='realestate' else '')+'</aside></section>'
        render('/businesses/'+p['slug']+'/',p['name']+' | Local Referral',p['intro']+' Find public contact details, linked sources and questions for the first conversation.',body)
        # Mark up only identity and contact information actually shown on the page.
        target=out/'businesses'/p['slug']/'index.html';s=target.read_text()
        entity={'@context':'https://schema.org','@type':'AutoRepair' if p['category']=='automotive' else 'Person','name':p['name'],'url':(origin or 'http://localhost:8123')+'/businesses/'+p['slug']+'/','telephone':p['tel'],'sameAs':p['website']}
        s=s.replace('</head>','<script type="application/ld+json">'+json.dumps(entity).replace('<','\\u003c')+'</script></head>');target.write_text(s)
    mechanic=PEOPLE[0];agents=PEOPLE[1:]
    auto='<div class="breadcrumb">'+link('/local-help/','Local help')+'<span>/</span>Auto mechanics</div><div class="local-intro"><div class="eyebrow">FOR WHAT GETS YOU THERE</div><h1>A good mechanic.<br><em>A clearer next step.</em></h1><p class="local-lede">Meet the local shop Wazoozie’s owner recommends. Start with your vehicle and the concern, then confirm the work and appointment directly.</p></div><div class="local-pro-grid">'+card(mechanic)+'</div><section class="local-question-band"><h2>Before the keys change hands.</h2><p>Describe the symptoms and ask what the diagnostic visit includes. Request a written estimate and agree how additional work will be approved. Keep the repair warranty with the final invoice.</p><p>'+link('https://consumer.ftc.gov/articles/0211-auto-repair-basics','Read the FTC’s auto-repair consumer guide ↗')+'</p></section><p>'+link('/for-contractors/?category=automotive#business-application','Own an auto shop? Apply for listing consideration →')+'</p>'
    render('/auto-mechanics/','Auto Mechanics & Repair | Local Referrals','Explore an owner-recommended auto repair shop, linked official contact details and questions to ask before service.',auto)
    real='<div class="breadcrumb">'+link('/local-help/','Local help')+'<span>/</span>Real estate agents</div><div class="local-intro"><div class="eyebrow">FOR THE NEXT CHAPTER</div><h1>A move starts<br><em>with a conversation.</em></h1><p class="local-lede">Meet the real estate professionals recommended by Wazoozie’s owner. Compare the people, ask about your plans and decide who you want to work with.</p></div><div class="local-pro-grid">'+''.join(card(p) for p in agents)+'</div><section class="local-question-band"><h2>The useful details, before a decision.</h2><p>Ask about the professional’s role, your property location, communication, proposed services and written terms. Public profile information is not an independent license-status check or a promise of a particular transaction result.</p><p>'+link('https://www.pals.pa.gov/pages/search.html','Look up Pennsylvania professional-license records ↗')+'</p></section><p>'+link('/for-contractors/?category=realestate#business-application','Work in real estate? Apply for consideration →')+'</p>'
    render('/real-estate-agents/','Local Real Estate Agents | Owner-Recommended Professionals','Meet Caitlin Kerezsi, Megan Kerezsi and Libbi Skivo through linked professional profiles and direct business contact details.',real)
    categories='<div class="local-category-grid"><a href="/#find"><span>01 / YOUR HOME</span><h2>Good help for the place you live.</h2><p>Heating, cooling, plumbing, electrical work, painting, carpentry and larger projects.</p><strong>Explore home services ↗</strong></a><a href="/auto-mechanics/"><span>02 / YOUR CAR</span><h2>A shop you can get to know.</h2><p>Start with an owner-recommended automotive business and the right questions.</p><strong>Meet the automotive referral ↗</strong></a><a href="/real-estate-agents/"><span>03 / YOUR NEXT CHAPTER</span><h2>The people behind the move.</h2><p>Meet recommended real estate professionals and discuss your plans directly.</p><strong>Explore real estate professionals ↗</strong></a></div>'
    overview='<div class="local-intro"><div class="eyebrow">YOUR LOCAL SHORTLIST. A LITTLE MORE OF LIFE.</div><h1>A good name<br><em>for what life needs.</em></h1><p class="local-lede">The house. The car. The next move. Wazoozie brings local recommendations, public business details and useful questions together, so the first conversation starts with more clarity.</p></div>'+categories+'<section class="local-question-band"><h2>Trust works better with context.</h2><p>New automotive and real estate profiles identify the owner’s recommendation, link their public sources and state what has not been independently checked. Existing home-service profiles retain their own evidence panels. A recommendation is not a guarantee; confirm the business, coverage, relevant credentials and written terms for your situation.</p>'+link('/our-standards/','Read the home-service directory standards →')+'</section><p>'+link('/for-contractors/','Introduce your local business →')+'</p>'
    render('/local-help/','Local Help | Home Services, Auto Mechanics & Real Estate','Find local home services, an owner-recommended automotive shop and real estate professionals, with direct contact details and linked sources.',overview)
    home=out/'index.html';s=home.read_text();teaser='<section class="wrap local-home-expansion" aria-labelledby="local-life-title"><div class="eyebrow">A LITTLE MORE OF LIFE, LOCALLY.</div><h2 id="local-life-title">The house. The car. The next chapter.</h2><p>One place to start with local recommendations and clear information.</p>'+categories+'</section>'
    s=s.replace('<section class="wrap journal-home"',teaser+'<section class="wrap journal-home"',1);home.write_text(s)
    for target in out.rglob('*.html'):
        s=target.read_text().replace('<a href="/#find">Find a pro</a>','<a href="/local-help/">Local help</a>')
        s=s.replace('<nav aria-label="Mobile navigation">','<nav aria-label="Mobile navigation"><a href="/local-help/">Explore local help</a>',1)
        s=s.replace('<strong>The useful details</strong>','<strong>The useful details</strong><a href="/local-help/">Home, auto &amp; real estate</a>',1)
        s=s.replace('</head>','<link rel="stylesheet" href="/assets/local-help.css"></head>',1) if target==home else s
        target.write_text(s)
    shutil.copy(out.parent/'assets/local-help.css',out/'assets/local-help.css')
